import { Category, ErrorEvent, Identity, PartyIdentification, SearchEvent } from '../events';
/**
Description: A product category is clicked to \"search\" for the products within that category.
*/
export type ClickCategory = {
    events: Array<SearchEvent | Identity | PartyIdentification | ErrorEvent>;
}

export class ClickCategoryBuilder {

    private clickCategory: ClickCategory = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private searchEvent!: SearchEvent;

    public withErrorEvent(errorEvent: ErrorEvent) : ClickCategoryBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ClickCategoryBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ClickCategoryBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withSearchEvent(searchEvent: SearchEvent) : ClickCategoryBuilder {
        this.searchEvent = searchEvent;
        return this;
    }

    public build() : ClickCategory {
        if(this.errorEvent) {
            this.clickCategory.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.clickCategory.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.clickCategory.events.push(this.partyIdentification);
        }
        if(this.searchEvent) {
            this.clickCategory.events.push(this.searchEvent);
        }

        return this.clickCategory;
    }
}
